     1	/**
     2	 * A quiet line in the footer saying which API, namespace and store the page is
     3	 * talking to, so an in-memory store is never mistaken for persistence (ADR-0004).
     4	 */
     5	import { useEffect, useState } from "react";
     6	import Typography from "@mui/material/Typography";
     7	import { healthResponseSchema, type HealthResponse } from "@auto-apply/shared";
     8	import { API_URL } from "../api";
     9	
    10	type State =
    11	  | { kind: "loading" }
    12	  | { kind: "error"; message: string }
    13	  | { kind: "ready"; health: HealthResponse };
    14	
    15	export function ApiHealth() {
    16	  const [state, setState] = useState<State>({ kind: "loading" });
    17	
    18	  useEffect(() => {
    19	    let cancelled = false;
    20	
    21	    fetch(`${API_URL}/api/health`)
    22	      .then(async (res) => {
    23	        if (!res.ok) {
    24	          throw new Error(`API responded ${res.status}`);
    25	        }
    26	        return healthResponseSchema.parse(await res.json());
    27	      })
    28	      .then((health) => {
    29	        if (!cancelled) {
    30	          setState({ kind: "ready", health });
    31	        }
    32	      })
    33	      .catch((err: unknown) => {
    34	        if (!cancelled) {
    35	          setState({
    36	            kind: "error",
    37	            message: err instanceof Error ? err.message : "Unknown error",
    38	          });
    39	        }
    40	      });
    41	
    42	    return () => {
    43	      cancelled = true;
    44	    };
    45	  }, []);
    46	
    47	  if (state.kind === "loading") {
    48	    return (
    49	      <Typography variant="caption" color="text.secondary">
    50	        Checking API…
    51	      </Typography>
    52	    );
    53	  }
    54	  if (state.kind === "error") {
    55	    return (
    56	      <Typography variant="caption" color="error" role="alert">
    57	        Could not reach the API: {state.message}
    58	      </Typography>
    59	    );
    60	  }
    61	  const { health } = state;
    62	  return (
    63	    <Typography variant="caption" color="text.secondary">
    64	      API {health.status} · namespace {health.namespace} ·{" "}
    65	      {health.repo === "memory" ? "In-memory (not persisted)" : "Firestore"}
    66	    </Typography>
    67	  );
    68	}
